```swift
import SwiftUI
import SwiftData
import AVFoundation

/// Крупная обложка с кнопками «Сфотографировать / Переснять / Удалить».
struct BookCoverEditor: View {
    let book: Book
    @Environment(\.modelContext) private var modelContext
    @Environment(\.openURL) private var openURL
    @State private var isCameraShown = false
    @State private var isSaving = false
    @State private var isCameraDeniedAlertShown = false
    @State private var saveFailed = false

    var body: some View {
        VStack(spacing: 12) {
            BookCoverView(coverID: book.coverID, variant: .full)
                .frame(maxWidth: 220)
                .overlay {
                    if isSaving {
                        ProgressView().controlSize(.large)
                    }
                }

            ViewThatFits(in: .horizontal) {
                HStack { buttons }
                VStack { buttons }
            }
            .buttonStyle(.bordered)
            .disabled(isSaving)
        }
        .fullScreenCover(isPresented: $isCameraShown) {
            CameraPicker { photo in
                isCameraShown = false
                if let photo {
                    setCover(from: photo)
                }
            }
            .ignoresSafeArea()
        }
        .alert("Нет доступа к камере", isPresented: $isCameraDeniedAlertShown) {
            Button("Открыть настройки") {
                if let url = URL(string: UIApplication.openSettingsURLString) {
                    openURL(url)
                }
            }
            Button("Отмена", role: .cancel) {}
        } message: {
            Text("Разрешите доступ к камере в Настройках, чтобы фотографировать обложки.")
        }
        .alert("Не удалось сохранить обложку", isPresented: $saveFailed) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("Попробуйте ещё раз. Если не помогает — проверьте свободное место на iPhone.")
        }
    }

    @ViewBuilder
    private var buttons: some View {
        if CameraPicker.isAvailable {
            Button(book.coverID == nil ? "Сфотографировать" : "Переснять", systemImage: "camera", action: openCamera)
        }
        if book.coverID != nil {
            Button("Удалить", systemImage: "trash", role: .destructive, action: removeCover)
        }
    }

    private func openCamera() {
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .denied, .restricted:
            isCameraDeniedAlertShown = true
        default:
            // При первом открытии система сама спросит разрешение.
            isCameraShown = true
        }
    }

    private func setCover(from photo: UIImage) {
        isSaving = true
        Task {
            defer { isSaving = false }
            do {
                let newID = try await CoverStore.shared.save(photo)
                let oldID = book.coverID
                book.coverID = newID
                do {
                    try modelContext.save()
                } catch {
                    book.coverID = oldID
                    CoverStore.shared.delete(id: newID)
                    throw error
                }
                // Старые файлы удаляем только после того, как новая обложка надёжно записана.
                if let oldID {
                    CoverStore.shared.delete(id: oldID)
                }
            } catch {
                saveFailed = true
            }
        }
    }

    private func removeCover() {
        guard let oldID = book.coverID else { return }
        book.coverID = nil
        do {
            try modelContext.save()
            CoverStore.shared.delete(id: oldID)
        } catch {
            book.coverID = oldID
            saveFailed = true
        }
    }
}
```

### 6. `CoverMaintenance.swift`: удаление книги и уборка «осиротевших» файлов

```swift
import SwiftUI
import SwiftData

extension ModelContext {
    /// Удаляет книгу вместе с файлами обложки.
    func deleteBook(_ book: Book) throws {
        let coverID = book.coverID
        delete(book)
        try save()
        if let coverID {
            CoverStore.shared.delete(id: coverID)
        }
    }
}

extension View {
    /// При появлении экрана убирает с диска обложки, которые не нужны ни одной книге.
    func cleansUpOrphanedCovers() -> some View {
        modifier(OrphanedCoversCleanup())
    }
}

private struct OrphanedCoversCleanup: ViewModifier {
    @Environment(\.modelContext) private var modelContext

    func body(content: Content) -> some View {
        content.task {
            var descriptor = FetchDescriptor<Book>(predicate: #Predicate { $0.coverID != nil })
            descriptor.propertiesToFetch = [\.coverID]
            // Если базу прочитать не удалось — ничего не удаляем.
            guard let books = try? modelContext.fetch(descriptor) else { return }
            let ids = Set(books.compactMap(\.coverID))
            await CoverStore.shared.removeOrphans(keeping: ids, olderThan: .now.addingTimeInterval(-3600))
        }
    }
}
```

