```swift
import SwiftData
import UIKit

@MainActor
enum BookCoverStore {
    static func setCover(_ photo: UIImage, for book: Book, in context: ModelContext) async throws {
        let rendered = try await CoverImageProcessor.process(photo)
        // The book may have been deleted while the photo was being processed.
        guard book.modelContext != nil, !book.isDeleted else { return }

        let old = book.cover
        book.cover = BookCover(imageData: rendered.full, thumbnailData: rendered.thumbnail)
        // Replacing a relationship does not delete the old object; without this it stays orphaned.
        if let old { context.delete(old) }
        try context.save()
    }

    static func removeCover(from book: Book, in context: ModelContext) throws {
        guard let cover = book.cover else { return }
        book.cover = nil
        context.delete(cover)
        try context.save()
    }
}
```

