import SwiftUI

struct BookCoverView: View {
    enum Style {
        case thumbnail
        case large
    }

    let book: Book
    var style: Style = .thumbnail

    @State private var loaded: (key: String, image: UIImage)?

    private var cacheKey: String? {
        guard let cover = book.cover else { return nil }
        return "\(cover.id.uuidString)-\(style == .thumbnail ? "thumb" : "full")"
    }

    /// Reads the cache synchronously so a re-created list row shows its cover without a blank frame.
    private var displayedImage: UIImage? {
        guard let key = cacheKey else { return nil }
        if let loaded, loaded.key == key { return loaded.image }
        return CoverImageCache.shared.image(for: key)
    }

    var body: some View {
        Rectangle()
            .fill(.quaternary)
            .overlay {
                if let image = displayedImage {
                    Image(uiImage: image)
                        .resizable()
                        .scaledToFill()
                } else {
                    Image(systemName: "book.closed")
                        .font(style == .thumbnail ? .body : .system(size: 48))
                        .foregroundStyle(.secondary)
                }
            }
            .clipShape(RoundedRectangle(cornerRadius: style == .thumbnail ? 4 : 10))
            .task(id: cacheKey) { await load() }
    }

    private func load() async {
        guard let key = cacheKey, let cover = book.cover else { return }
        if CoverImageCache.shared.image(for: key) != nil { return }

        let data = style == .thumbnail ? cover.thumbnailData : cover.imageData
        // Decoding happens off the main thread.
        guard let image = await UIImage(data: data)?.byPreparingForDisplay() else { return }
        CoverImageCache.shared.insert(image, for: key)
        if !Task.isCancelled {
            loaded = (key, image)
        }
    }
}
