struct BookDetailView: View {
    let book: Book

    @Environment(\.modelContext) private var modelContext
    @State private var isCameraPresented = false
    @State private var isSavingCover = false
    @State private var showsCoverError = false

    var body: some View {
        ScrollView {
            VStack(spacing: 16) {
                BookCoverView(book: book, style: .large)
                    .frame(width: 200, height: 300)
                    .overlay {
                        if isSavingCover { ProgressView() }
                    }
                    .shadow(radius: 6, y: 3)
                    .accessibilityLabel(book.cover == nil ? "Нет обложки" : "Обложка книги")
                Text(book.title)
                    .font(.title2.bold())
                    .multilineTextAlignment(.center)
                Text(book.author)
                    .foregroundStyle(.secondary)
            }
            .padding()
            .frame(maxWidth: .infinity)
        }
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .primaryAction) {
                Menu {
                    Button("Сфотографировать обложку", systemImage: "camera") {
                        isCameraPresented = true
                    }
                    .disabled(!CameraPicker.isAvailable)
                    if book.cover != nil {
                        Button("Удалить обложку", systemImage: "trash", role: .destructive) {
                            removeCover()
                        }
                    }
                } label: {
                    Label("Обложка", systemImage: "photo")
                }
                .disabled(isSavingCover)
            }
        }
        .fullScreenCover(isPresented: $isCameraPresented) {
            CameraPicker { photo in
                isCameraPresented = false
                if let photo {
                    Task { await saveCover(photo) }
                }
            }
            .ignoresSafeArea()
        }
        .alert("Не удалось сохранить обложку", isPresented: $showsCoverError) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("Попробуйте сфотографировать ещё раз.")
        }
    }

    private func saveCover(_ photo: UIImage) async {
        isSavingCover = true
        defer { isSavingCover = false }
        do {
            try await BookCoverStore.setCover(photo, for: book, in: modelContext)
        } catch {
            showsCoverError = true
        }
    }

    private func removeCover() {
        do {
            try BookCoverStore.removeCover(from: book, in: modelContext)
        } catch {
            showsCoverError = true
        }
    }
}
