### 3. `CoverImageProcessor.swift`

```swift
import UIKit

nonisolated enum CoverImageProcessor {
    struct Output: Sendable {
        let full: Data
        let thumbnail: Data
    }

    enum Failure: Error {
        case encodingFailed
    }

    static let fullMaxPixels: CGFloat = 1200
    static let thumbnailMaxPixels: CGFloat = 240

    /// Shrinks a camera photo off the main thread. Orientation is baked into the pixels.
    static func process(_ photo: UIImage) async throws -> Output {
        try await Task.detached(priority: .userInitiated) {
            let full = resized(photo, maxPixelSide: fullMaxPixels)
            // Thumbnail from the already reduced image: better quality than a 16x jump in one step.
            let thumbnail = resized(full, maxPixelSide: thumbnailMaxPixels)
            guard
                let fullData = full.jpegData(compressionQuality: 0.8),
                let thumbnailData = thumbnail.jpegData(compressionQuality: 0.75)
            else { throw Failure.encodingFailed }
            return Output(full: fullData, thumbnail: thumbnailData)
        }.value
    }

    private static func resized(_ image: UIImage, maxPixelSide: CGFloat) -> UIImage {
        let pixelWidth = image.size.width * image.scale
        let pixelHeight = image.size.height * image.scale
        let factor = min(1, maxPixelSide / max(pixelWidth, pixelHeight))
        let size = CGSize(width: (pixelWidth * factor).rounded(), height: (pixelHeight * factor).rounded())

        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        format.opaque = true
        format.preferredRange = .standard
        return UIGraphicsImageRenderer(size: size, format: format).image { _ in
            image.draw(in: CGRect(origin: .zero, size: size))
        }
    }
}
```

