                    Label("Обложка", systemImage: "photo")
                }
                .disabled(isSavingCover)
            }
        }
        .fullScreenCover(isPresented: $isCameraPresented) {
            CameraPicker { photo in
                isCameraPresented = false
                if let photo {
                    Task { await saveCover(photo) }
                }
            }
            .ignoresSafeArea()
        }
        .alert("Не удалось сохранить обложку", isPresented: $showsCoverError) {
            Button("OK", role: .cancel) {}
        } message: {
            Text("Попробуйте сфотографировать ещё раз.")
        }
    }

    private func saveCover(_ photo: UIImage) async {
        isSavingCover = true
        defer { isSavingCover = false }
        do {
            try await BookCoverStore.setCover(photo, for: book, in: modelContext)
        } catch {
            showsCoverError = true
        }
    }

    private func removeCover() {
        do {
            try BookCoverStore.removeCover(from: book, in: modelContext)
        } catch {
            showsCoverError = true
        }
    }
}
```

**Регистрация модели** (в файле `App`, где сейчас подключается `Book`):

```swift
.modelContainer(for: [Book.self, BookCover.self])
```

**Info.plist**: ключ `NSCameraUsageDescription` со значением, например, «Камера нужна, чтобы сфотографировать обложку книги».

### 10. `BookCoverTests.swift` (тестовая цель, Swift Testing)

```swift
import SwiftData
import Testing
import UIKit
@testable import Slumpy

@MainActor
struct BookCoverTests {
    /// A 12 MP camera frame: landscape pixels marked as rotated, like a portrait shot from the camera.
    private func cameraPhoto() throws -> UIImage {
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        let pixels = UIGraphicsImageRenderer(size: CGSize(width: 4032, height: 3024), format: format).image { context in
            UIColor.systemTeal.setFill()
            context.fill(CGRect(x: 0, y: 0, width: 4032, height: 3024))
        }
        let cgImage = try #require(pixels.cgImage)
        return UIImage(cgImage: cgImage, scale: 1, orientation: .right)
    }

    @Test func cameraPhotoIsShrunkAndStaysPortrait() async throws {
        let output = try await CoverImageProcessor.process(try cameraPhoto())

        let full = try #require(UIImage(data: output.full))
        let thumbnail = try #require(UIImage(data: output.thumbnail))
        #expect(full.size == CGSize(width: 900, height: 1200))
        #expect(thumbnail.size == CGSize(width: 180, height: 240))
    }

    @Test func replacingCoverKeepsOnlyNewOneAndDeletingBookRemovesIt() async throws {
        let container = try ModelContainer(
            for: Book.self, BookCover.self,
            configurations: ModelConfiguration(isStoredInMemoryOnly: true)
        )
        let context = container.mainContext
        let book = Book(title: "Мастер и Маргарита", author: "Булгаков")
        context.insert(book)
        let photo = try cameraPhoto()

        try await BookCoverStore.setCover(photo, for: book, in: context)
        let firstCoverID = try #require(book.cover?.id)
        try await BookCoverStore.setCover(photo, for: book, in: context)

        let covers = try context.fetch(FetchDescriptor<BookCover>())
        #expect(covers.count == 1)
        #expect(covers.first?.id != firstCoverID)

        context.delete(book)
        try context.save()
        #expect(try context.fetchCount(FetchDescriptor<BookCover>()) == 0)
    }
}
